/** 作詞・作曲の欄(「Reol,Giga」「ツミキ・Reol」「Reol, Masayoshi Iimori」)を一人ずつに分ける */
const splitMembers = (value: string | null | undefined): string[] => (value ?? "").split(/\s*[,、・]\s*/);

/**
 * 楽曲記事のタグ。初出の作品名、その作品の名義(れをる / REOL / Reol など。管理表の表記のまま)、
 * 作詞者、作曲者(一人ずつ)に、編集で足したタグを加える。重複と空文字は除き、順序は 作品 → 名義 → 作詞 → 作曲 → 編集タグ。
 * 2026-11-05 ユーザー「〜年というタグは不要だかられをるの名義(れをるなのかREOLなのかReolなのか...)と作詞作曲者の名前をタグにしてほしい」
 */
export const songArticleTags = (input: {
  releases: { title: string; releaseDate: string | null; artist?: string | null }[];
  lyricMember?: string | null;
  musicMember?: string | null;
  extra?: string[] | null;
}): string[] => {
  const first = input.releases[0] ?? null;
  const tags = [
    first?.title ?? null,
    first?.artist ?? null,
    ...splitMembers(input.lyricMember),
    ...splitMembers(input.musicMember),
    ...(input.extra ?? []),
  ]
    .map((t) => (t ?? "").trim())
    .filter((t) => t !== "");
  return [...new Set(tags)];
};

/**
 * 読みもの一覧でまとめる作品(?album= の絞り込みも同じ)。シングルよりアルバム・EP など曲数の多いまとまりを優先する
 * (2026-11-06 ユーザー「平面鏡は虚構集に入れて。グルーピングはシングルよりアルバムやEPなどより曲数の多いまとまりが優先」)。
 * 形式の順: アルバム・ミニアルバム・EP → アナログ盤 → シングル → 配信シングルなど → ライヴ映像。同じ順なら発売の早い方。
 * 曲数だけで選ぶと、武道館のライヴ盤(fullAL・12曲)が『No title-』(11曲)より先に来てしまうので形式で比べる。
 */
const GROUPING_FORMAT_RANK: Record<string, number> = { fullAL: 0, miniAL: 0, EP: 0, LP: 1, SG: 2, "DVD/BD": 4 };
export const groupingRelease = <T extends { title: string; format?: string | null; releaseDate: string | null }>(releases: T[]): T | null => {
  const rank = (r: T) => GROUPING_FORMAT_RANK[r.format ?? ""] ?? 3;
  return (
    [...releases].sort((a, b) => rank(a) - rank(b) || (a.releaseDate ?? "9999").localeCompare(b.releaseDate ?? "9999"))[0] ?? null
  );
};

/** 一覧の絞り込み URL(タグは日本語を含むのでエンコードする) */
export const tagFilterPath = (tag: string): string => `/articles/?tag=${encodeURIComponent(tag)}`;
export const seriesPath = (slug: string): string => `/articles/series/${slug}/`;

/**
 * HOME の「読みもの」のカルーセルに出す本数。公開日時の新しい順(2026-11-04 ユーザー「表示件数は10枚はどう？」。plan/59)。
 * いちばん新しい1本はカルーセルの上に大きく出すので、HOME にはこれ+1本を渡す。
 * それまでは手で選んだ3本(No title → drop pop candy → 1LDK)だった。
 */
export const HOME_ARTICLE_COUNT = 10;

/**
 * カードの上に小さく曲名を出すか。題名にもう曲名が入っている時(「MONSTER 欲しがる…」「…読み直すNo title」)は出さない
 * (同じ語が続いて見えるため。2026-10-12 ユーザー指定)。大文字小文字は区別しない
 */
export const showSongKicker = (title: string, songTitle: string): boolean => {
  // 曲名の末尾の括弧書き(「drop pop candy (feat. ギガ)」の「(feat. ギガ)」など)は外して比べる
  const core = songTitle.replace(/\s*[(（][^()（）]*[)）]\s*$/, "").trim() || songTitle;
  return !title.toLowerCase().includes(core.toLowerCase());
};

/**
 * 題名の中の曲名の位置(曲名を強調して表示するため)。曲名の末尾の括弧書き(feat. など)は外し、大文字小文字は区別しない。
 * 見つからなければ null。2026-10-13 ユーザー「読み物一覧において曲名の文字だけ強調表示してください」
 */
export const splitTitleBySong = (title: string, songTitle: string): { before: string; song: string; after: string } | null => {
  const core = songTitle.replace(/\s*[(（][^()（）]*[)）]\s*$/, "").trim() || songTitle;
  const at = title.toLowerCase().indexOf(core.toLowerCase());
  if (at < 0 || !core) return null;
  return { before: title.slice(0, at), song: title.slice(at, at + core.length), after: title.slice(at + core.length) };
};

export type RelatedCandidate = {
  id: string;
  slug: string;
  title: string;
  songTitle: string;
  seriesSlug: string;
  tags: string[];
  createdAt: string | null;
  /** 公開日時(予約公開の判定に使う。plan/43) */
  publishedAt?: string | null;
};

/**
 * 記事ページの下部に出す関連記事(2026-10-11)。最大 limit 本。
 * 編集で指定した関連記事(relatedArticleIds)を先に、残りは
 * 共通のタグの数(作品・年)→ 同じシリーズ → 作成日の新しい順 で選ぶ。自分自身は除く。
 */
export const pickRelatedArticles = (
  self: { id: string; seriesSlug: string; tags: string[]; relatedArticleIds?: string[] | null },
  all: RelatedCandidate[],
  limit = 3
): RelatedCandidate[] => {
  const others = all.filter((a) => a.id !== self.id);
  const chosen: RelatedCandidate[] = [];
  for (const id of self.relatedArticleIds ?? []) {
    const hit = others.find((a) => a.id === id);
    if (hit && !chosen.includes(hit)) chosen.push(hit);
  }
  const score = (a: RelatedCandidate) =>
    a.tags.filter((t) => self.tags.includes(t)).length * 2 + (a.seriesSlug === self.seriesSlug ? 1 : 0);
  const rest = others
    .filter((a) => !chosen.includes(a))
    .sort((a, b) => score(b) - score(a) || (b.createdAt ?? "").localeCompare(a.createdAt ?? ""));
  return [...chosen, ...rest].slice(0, limit);
};
